<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import api from '../services/api'
import axios from 'axios'
import { Calendar, BookOpen, ArrowRight, Loader2, Search, Sparkles, CheckCircle2, GraduationCap, Users, LogIn, Layers, ChevronDown, ChevronUp, HelpCircle, Mail, PlayCircle, Clock
} from 'lucide-vue-next' const router = useRouter()
const campaigns = ref([])
const formations = ref([])
const loading = ref(true)
const loadingFormations = ref(true)
const searchQuery = ref('')
const selectedFormation = ref(null)
const showAllFormations = ref(false) const displayedFormations = computed(() => { if (showAllFormations.value) { return formations.value } return formations.value.slice(0, 3)
}) // Section Impact Logic
const impactSectionRef = ref(null)
let hasAnimated = false const impactStats = ref([ { id: 1, prefix: '+', target: 35000, suffix: '', label: 'Personnes Formées', current: 0 }, { id: 2, prefix: '', target: 95, suffix: '%', label: 'Taux d\'insertion professionnelle', current: 0 }, { id: 3, prefix: '+', target: 55, suffix: '%', label: 'Femmes Formées', current: 0 }, { id: 4, prefix: '', target: 14, suffix: '', label: 'Régions d\'interventions', current: 0 }, { id: 5, prefix: '+', target: 250, suffix: '', label: 'Partenaires', current: 0 }, { id: 6, prefix: '+', target: 40, suffix: '', label: 'collaborateurs', current: 0 }, { id: 7, prefix: '+', target: 29, suffix: '', label: 'projets réalisés', current: 0 }, { id: 8, prefix: '+', target: 120, suffix: '', label: 'localités couvertes', current: 0 }
]) const animateNumbers = () => { impactStats.value.forEach(stat => { const duration = 2000 const steps = 60 const stepTime = Math.abs(Math.floor(duration / steps)) const increment = stat.target / steps let currentStep = 0 const timer = setInterval(() => { currentStep++ stat.current = Math.min(Math.round(increment * currentStep), stat.target) if (currentStep >= steps) { stat.current = stat.target clearInterval(timer) } }, stepTime) })
} onMounted(async () => { if (impactSectionRef.value) { const observer = new IntersectionObserver((entries) => { if (entries[0].isIntersecting && !hasAnimated) { hasAnimated = true animateNumbers() } }, { threshold: 0.3 }) observer.observe(impactSectionRef.value) } try { const [campRes, formRes] = await Promise.all([ api.get('campagnes/publiques/'), axios.get('http://127.0.0.1:8000/api/campagnes/formations/publiques/') ]) campaigns.value = campRes.data formations.value = formRes.data } catch (error) { console.error('Erreur lors du chargement des données publiques', error) } finally { loading.value = false loadingFormations.value = false }
}) const filteredCampaigns = computed(() => { let result = campaigns.value // Filtre par formation sélectionnée if (selectedFormation.value) { result = result.filter(camp => camp.formation_nom === selectedFormation.value) } // Filtre par recherche texte if (searchQuery.value.trim()) { const query = searchQuery.value.toLowerCase() result = result.filter( (camp) => camp.nom?.toLowerCase().includes(query) || camp.formation_nom?.toLowerCase().includes(query) || camp.cohorte_nom?.toLowerCase().includes(query) || camp.description?.toLowerCase().includes(query) ) } return result
}) const selectFormation = (formationNom) => { selectedFormation.value = selectedFormation.value === formationNom ? null : formationNom // Scroller vers les campagnes setTimeout(() => { const el = document.getElementById('campagnes') if (el) el.scrollIntoView({ behavior: 'smooth' }) }, 100)
} // FAQ Data
const faqs = ref([ { question: 'Quels sont les prérequis pour postuler à une formation Simplon ?', answer: 'Nos formations sont accessibles à toutes et à tous, sans condition de diplôme préalable. Nous privilégions la motivation réelle, la curiosité, l’appétence pour le numérique et la rigueur dans l’apprentissage.', category: 'Prérequis & Inscription' }, { question: 'Comment se déroule le processus de sélection ?', answer: 'Le processus comprend 3 grandes étapes : le dépôt du dossier de candidature en ligne, le passage des tests de positionnement (QCM technique et logique), puis un entretien individuel pour évaluer votre projet professionnel et votre motivation.', category: 'Processus de sélection' }, { question: 'Les formations sont-elles gratuites ?', answer: 'Oui, la grande majorité de nos formations certifiantes et qualifiantes sont 100% gratuites et intensives pour les apprenants retenus, grâce au soutien de nos partenaires institutionnels et entreprises.', category: 'Coût & Financement' }, { question: 'Puis-je postuler à plusieurs campagnes en même temps ?', answer: 'Nous vous conseillons de postuler à la campagne qui correspond le mieux à votre projet professionnel. Si votre candidature n’est pas retenue, vous aurez l’opportunité de repostuler lors des prochaines cohortes.', category: 'Candidatures' }, { question: 'Comment suivre l’état d’avancement de ma candidature ?', answer: 'Dès la soumission de votre dossier, vous recevrez des confirmations et alertes par email. Vous pouvez également vous connecter à votre espace candidat pour consulter l’état de validation de vos étapes.', category: 'Suivi de dossier' }, { question: 'Obtient-on une certification ou un diplôme reconnu ?', answer: 'Oui, à l’issue de votre parcours et après validation des compétences, vous obtenez un titre professionnel ou une certification reconnue par l’État et très prisée sur le marché de l’emploi numérique.', category: 'Certifications' }
]) const openFaqIndex = ref(0) const toggleFaq = (index) => { openFaqIndex.value = openFaqIndex.value === index ? null : index
} const isFaqOpen = (index) => openFaqIndex.value === index const scrollToTop = () => { window.scrollTo({ top: 0, behavior: 'smooth' })
} const scrollToFaq = () => { const el = document.getElementById('faq') if (el) { el.scrollIntoView({ behavior: 'smooth' }) }
}
