Q</a> </nav> <!-- Right actions --> <div class="flex items-center shrink-0"> <button @click="router.push('/login')" class="group inline-flex items-center gap-2 px-5 py-2.5 sm:px-6 sm:py-3 rounded-full text-sm font-extrabold text-white bg-[#01313E] hover:bg-[#E30046] transition-colors duration-300" > <LogIn class="w-4 h-4 transition-transform group-hover:-translate-x-1"/> <span class="hidden sm:inline">Espace Connexion</span> <span class="sm:hidden">Connexion</span> </button> </div> </div> </div> </header> <!-- Spacer pour compenser la navbar fixed --> <div class="h-20 sm:h-28 bg-[#E2E2E2] w-full"></div> <!-- Hero Section --> <section class="relative bg-[#E2E2E2] w-full"> <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-12 pb-16 lg:pt-20 lg:pb-24"> <div class="grid grid-cols-1 lg:grid-cols-2 gap-8 lg:gap-16 items-center"> <!-- Colonne Gauche: Vidéo --> <div class="w-full flex items-center justify-center"> <video src="/videos/propulser-1.mp4" autoplay loop muted playsinline class="w-full h-auto object-contain object-top rounded-3xl" ></video> </div> <!-- Colonne Droite: Texte --> <div class="text-left"> <h1 class="text-4xl sm:text-5xl lg:text-6xl font-black text-[#01313E] tracking-tight leading-tight"> Propulsez votre avenir avec nos <br class="hidden lg:block"/><span class="text-[#E30046]">formations qualifiantes</span> </h1> <p class="mt-6 text-lg sm:text-xl text-[#01313E]/80 font-normal leading-relaxed"> Découvrez les cohortes de formation ouvertes et posez votre candidature en quelques clics pour vous former aux métiers du numérique. </p> </div> </div> </div> </section> <!-- Section: Impact --> <section id="impact" ref="impactSectionRef" class="max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 my-12 lg:my-20"> <div class="rounded-[2rem] overflow-hidden transition- duration-300"> <!-- Header --> <div class="bg-[#E30046] py-8 text-center"> <h2 class="text-3xl sm:text-4xl lg:text-5xl font-black text-white tracking-tight">Notre Impact depuis 2018</h2> </div> <!-- Grid --> <div class="bg-[#01313E] p-8 sm:p-12 grid grid-cols-2 lg:grid-cols-4 gap-y-12 gap-x-6 text-center"> <div v-for="stat in impactStats" :key="stat.id" class="flex flex-col items-center justify-center"> <div class="text-4xl sm:text-5xl lg:text-6xl font-black text-white mb-2 tracking-tight"> {{ stat.prefix }}<span class="tabular-nums">{{ stat.current.toLocaleString('fr-FR').replace(/\u202f/g, ' ') }}</span>{{ stat.suffix }} </div> <div class="text-sm sm:text-base font-medium text-white/90"> {{ stat.label }} </div> </div> </div> </div> </section> <!-- Wrapper Formations & Campagnes --> <div class="w-full" style="background-color: #E2E2E2;"> <!-- Section: Formations --> <section id="formations" class="max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-16 lg:py-24"> <div class="mb-12 lg:mb-16 text-center"> <h2 class="text-3xl sm:text-4xl font-extrabold text-[#01313E]">Nos Formations</h2> <p class="text-[#01313E]/60 mt-3 text-base max-w-2xl mx-auto"> Découvrez les parcours d'apprentissage que nous proposons actuellement. Sélectionnez une formation pour voir ses campagnes. </p> </div> <div v-if="loadingFormations" class="flex flex-col items-center justify-center py-12"> <Loader2 class="w-10 h-10 animate-spin text-[#E30046] mb-4"/> <p class="text-sm text-[#01313E]/60 font-medium">Chargement des formations...</p> </div> <div v-else-if="formations.length === 0" class="text-center py-12 bg-white rounded-3xl border border-[#01313E]/10 max-w-md mx-auto"> <BookOpen class="w-10 h-10 text-[#01313E]/40 mx-auto mb-3"/> <p class="text-[#01313E]/60 font-medium">Aucune formation n'a été créée pour le moment.</p> </div> <div v-else class="space-y-8"> <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6"> <div v-for="form in displayedFormations" :key="form.id" @click="selectFormation(form.nom)" class="bg-white border p-6 sm:p-8 rounded-3xl cursor-pointer transition-all duration-300 group flex flex-col h-full hover:-translate-y-1" :class="selectedFormation === form.nom ? 'border-[#E30046] ring-2 ring-[#E30046]/20 bg-[#E30046]/5 ' : 'border-[#01313E]/10 hover:border-[#E30046]/40'" > <div class="flex items-start justify-between mb-5"> <div class="w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 transition-colors" :class="selectedFormation === form.nom ? 'bg-[#E30046] text-white' : 'bg-[#01313E]/5 text-[#01313E] group-hover:bg-[#E30046]/10 group-hover:text-[#E30046]'"> <BookOpen class="w-6 h-6"/> </div> <span class="text-xs font-bold px-3 py-1.5 rounded-full whitespace-nowrap" :class="selectedFormation === form.nom ? 'bg-white text-[#E30046] border border-[#E30046]/20' : 'bg-[#E30046]/10 text-[#E30046]'"> {{ form.nb_campagnes_actives > 0 ? 'Campagne ouverte' : 'Pas de campagne' }} </span> </div> <h3 class="text-xl font-extrabold text-[#01313E] mb-3 leading-tight">{{ form.nom }}</h3> <p class="text-sm text-[#01313E]/70 line-clamp-3 flex-1 leading-relaxed"> {{ form.description || 'Formation intensive et professionnalisante.' }} </p> </div> </div> <div v-if="formations.length > 3" class="flex justify-center mt-6"> <button @click="showAllFormations = !showAllFormations" class="px-6 py-2.5 rounded-xl border border-[#01313E]/10 hover:border-[#E30046]/40 hover:bg-[#E30046]/5 text-[#01313E] font-bold text-sm transition-all flex items-center gap-2" > {{ showAllFormations ? 'Voir moins' : 'Voir tout' }} <ChevronDown v-if="!showAllFormations" class="w-4 h-4"/> <ChevronUp v-else class="w-4 h-4"/> </button> </div> </div> </section> <!-- Main Content / Liste des campagnes --> <main id="campagnes" class="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 pb-20 scroll-mt-24"> <div class="flex flex-col sm:flex-row sm:items-end justify-between mb-8 pb-4 border-b border-[#01313E]/10 gap-4"> <div> <h2 class="text-2xl sm:text-3xl font-extrabold text-[#01313E]"> Campagnes disponibles </h2> <div v-if="selectedFormation" class="inline-flex items-center gap-2 mt-2 px-3 py-1 rounded-full bg-[#E30046]/10 text-[#E30046] text-xs font-bold"> <span>Filtre : {{ selectedFormation }}</span> <button @click="selectFormation(selectedFormation)" class="hover:text-black focus:outline-none" aria-label="Retirer le filtre"> &times; </button> </div> <p class="text-sm text-[#01313E]/60 mt-2"> Postulez avant la date limite de clôture indiquée. </p> </div> <span class="text-xs font-bold px-3 py-1.5 rounded-full bg-white text-[#01313E]/80 border border-[#01313E]/10 whitespace-nowrap self-start sm:self-auto"> {{ filteredCampaigns.length }} {{ filteredCampaigns.length > 1 ?'campagnes' :'campagne' }} </span> </div> <!-- State: Loading --> <div v-if="loading"class="flex flex-col items-center justify-center py-20"> <Loader2 class="w-12 h-12 animate-spin text-[#E30046] mb-4"/> <p class="text-sm text-[#01313E]/60 font-medium">Chargement des campagnes de recrutement...</p> </div> <!-- State: Empty --> <div v-else-if="filteredCampaigns.length === 0"class="text-center py-16 bg-white rounded-3xl border border-[#01313E]/10 max-w-md mx-auto p-8"> <div class="w-16 h-16 bg-white text-[#E30046] rounded-2xl flex items-center justify-center mx-auto mb-4"> <Calendar class="w-8 h-8"/> </div> <h3 class="text-lg font-bold text-[#01313E] mb-2">Aucune campagne disponible</h3> <p class="text-[#01313E]/60 text-sm"> {{ searchQuery ?"Aucun résultat ne correspond à votre recherche.":"Il n'y a actuellement aucune campagne de recrutement en cours."}} </p> <button v-if="searchQuery" @click="searchQuery =''" class="mt-4 px-4 py-2 bg-white hover:bg-white text-[#01313E]/80 rounded-xl text-xs font-bold transition-colors" > Réinitialiser la recherche </button> </div> <!-- State: Grid of Campaigns --> <div v-else class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"> <div v-for="camp in filteredCampaigns" :key="camp.id" class="group bg-white rounded-3xl border border-[#01313E]/10 hover:border-[#E30046]/40 hover:-translate-y-1 transition-all duration-300 flex flex-col justify-between overflow-hidden relative" > <!-- Accent line top on hover --> <div class="h-1.5